#!/usr/bin/env python3
"""Independent P9-2.2 boundary probes. Does not alter production or frozen inputs.

Run in the project environment:
  PYTHONPATH=src python P9-2.2-independent-stress-tests.py --repo . --output results.json

Node is an independent JCS oracle for constructing mutation identities; frozen
vectors supply their own expected bytes and IDs. No vector-builder imports.
Optional --isolated-audit-harness PATH is an AUDIT-ONLY reproduction mode. It
replaces unavailable JCS/packaged-schema providers, not the uploaded modules.
That mode is not installed-package, dependency, or G1 verification.
"""
from __future__ import annotations
import argparse,copy,hashlib,importlib,json,math,operator,os,platform,random,struct,subprocess,sys
from collections import Counter
