def main():
 ap=argparse.ArgumentParser(description=__doc__)
 ap.add_argument('--repo',type=Path,required=True)
 ap.add_argument('--output',type=Path,required=True)
 ap.add_argument('--isolated-audit-harness',type=Path)
 a=ap.parse_args();root=a.repo.resolve()
 if a.isolated_audit_harness:
  sys.path.insert(0,str(a.isolated_audit_harness.resolve()))
  importlib.import_module('harness')
 sys.path[:0]=[str(root/'src'),str(root)]
 c=importlib.import_module('pygrc.models.grc_v4_codec');p=importlib.import_module('pygrc.models.grc_v4_profile');s=importlib.import_module('pygrc.models.grc_v4_state')
 B=json.loads((root/'specs/grc-v4-conformance-vectors.json').read_text())
 S=json.loads((root/'specs/grc-v4-contract-schema.json').read_text())
 rows=[]
 # Independent ECMAScript/JCS oracle. The project implementation does not supply
 # expectations or decide which mutation should be admitted.
 js=r'''const rl=require('node:readline');function j(x){if(x===null||typeof x!=='object')return JSON.stringify(x);if(Array.isArray(x))return '['+x.map(j).join(',')+']';return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+j(x[k])).join(',')+'}'}rl.createInterface({input:process.stdin}).on('line',s=>console.log(JSON.stringify(j(JSON.parse(s)))));'''
 oracle=subprocess.Popen(['node','-e',js],stdin=subprocess.PIPE,stdout=subprocess.PIPE,text=True)
 def jcs(v):
  oracle.stdin.write(json.dumps(v,ensure_ascii=True,allow_nan=False)+'\n');oracle.stdin.flush()
  return json.loads(oracle.stdout.readline()).encode('utf-8')
 def ident(prefix,v):return prefix+':'+hashlib.sha256(jcs(v)).hexdigest()
 def req(v,msg='assertion failed'):
  if not v:raise AssertionError(msg)
 def check(name,group,fn,tier='required'):
  try:obs=fn();row={'id':name,'group':group,'tier':tier,'pass':True,'observed':obs}
  except Exception as e:row={'id':name,'group':group,'tier':tier,'pass':False,'exception':type(e).__name__,'message':str(e)}
  rows.append(row)
 def rejects(fn,types_=(c.V4WireError,c.V4SchemaError,c.V4IdentityError)):
  try:result=fn()
  except types_ as e:return {'exception':type(e).__name__,'message':str(e)[:300]}
  raise AssertionError('invalid input accepted: '+repr(result)[:200])
 def base():return copy.deepcopy(B['identity_vectors'][0]['payload']),copy.deepcopy(B['identity_vectors'][1]['payload'])
 def fixture(cand='C',real='OS'):
  par,i=base()
  if cand=='A':
   par['candidate']={'schema_version':'grcv4-candidate-a-params-v1','eta':1,'kappa_c':0,'site_potential_id':'audit_site_v1','W_floor':.1,'alpha':1,'beta':1,'gamma':1,'kappa_Ah':0,'chi_A':1,'zeta_A':1,'tau_A':1,'descriptor_backend_id':'audit_descriptor_v1','conductance_evaluator_id':'curvature_disabled_G_W_v1'}
   par['geometry']['candidate_adapter_id']='audit_A_adapter_v1';par['lifecycle']['history_policy_id']='audit_A_history_v1'
  ci={'schema_version':'grcv4-ci-params-v1','contraction_domain_id':'audit_domain_v1','root_selector_id':'unique_admitted_root_v1','iteration_limit':10,'residual_norm_id':'audit_norm_v1','tolerance':0}
  pc={'schema_version':'grcv4-pc-params-v1','tau_PC':1,'radius':1,'carrier_norm_id':'audit_norm_v1','source_envelope_id':'audit_envelope_v1','writer_id':'zero_order_hold_exponential_v1'}
  if real=='CI':par['realization']=ci
  elif real=='PC':par['realization']=pc
  elif real=='CI+PC':par['realization']={**ci,**pc,'schema_version':'grcv4-cipc-params-v1','rho_inst':1}
  elif real=='RG2b':par['realization']={'schema_version':'grcv4-rg2b-params-v1','extension_evaluator_id':'audit_evaluator_v1','approximation_policy_id':'audit_approx_v1','error_norm_id':'audit_norm_v1','error_tolerance':0,'containment_certificate_id':'audit_certificate_v1','iteration_limit':10,'failure_policy_id':'fail_closed_on_uncertified_section_v1'}
  i.update(candidate=cand,realization=real,profile_family_id=f"{cand}_{real.replace('+','_')}",candidate_c_transport_id='C-HM-STIFFNESS-BASELINE-v1' if cand=='C' else None,composition_gain=2 if real=='CI+PC' else None)
  i['params_hash']=ident('grcv4-params-sha256',par)
  return par,i
 def reidentify(par,i):i['params_hash']=ident('grcv4-params-sha256',par)
 def direct(par):
  rr=p.GRCV4ResolvedParams.from_payload(par)
  return type(rr)(**{f.name:getattr(rr,f.name) for f in fields(rr)})
 # Published golden content: finite examples cannot establish all-range closure.
 for v in B['canonicalization_vectors']+B['identity_vectors']+B['subdigest_identity_vectors']:
  def test(v=v):
   b=c.canonical_json_bytes(v['payload']);req(b==v['canonical_jcs_utf8'].encode());req(b.hex()==v['canonical_jcs_utf8_hex']);req(hashlib.sha256(b).hexdigest()==v['expected_identifier'].split(':')[1]);req(b==jcs(v['payload']))
   if v['schema_ref']!='RFC8785':req(c.payload_identity(v['schema_ref'],v['payload'])==v['expected_identifier'])
   return {'golden_id':v['expected_identifier']}
  check(v['vector_id'],'published_preimages',test)
 # Round-trip closure: distinguish a numeric token policy gap from serializer errors.
 vals=[0.,1.,-1.,.125,-.125,math.nextafter(float(2**53),0),float(2**53),math.nextafter(float(2**53),math.inf),1e16,1e17,1e18,1e19,1e20,math.nextafter(1e21,0),1e21,1e22,2.**68,5e-324,1e-6,1e-7,sys.float_info.max]
 vals += [-x for x in vals if x>0 and x>=2**53]
 for n,v in enumerate(vals):
  def roundtrip(v=v):
   b=c.canonical_json_bytes({'value':v})
   try:got=c.decode_json(b)
   except c.V4WireError as e:raise AssertionError(f'accepted float {v!r}; canonical={b!r}; decode fails: {e}')
   req(c.canonical_json_bytes(got)==b);return {'input':repr(v),'canonical':b.decode()}
  check('NUMERIC-ROUNDTRIP-'+str(n),'numeric_codec_composition',roundtrip,'integration_contract')
 # Numeric boundaries still reject prohibited native integral input/coercion.
 invalid=[-0.,float('nan'),float('inf'),2**53,-2**53,True]
 for v in invalid[:-1]:
  check('NATIVE-REJECT-'+repr(v),'native_numeric_rejection',lambda v=v:rejects(lambda:c.json_value(v)))
 for t in ['{"x":1,"x":2}','{"x":1,"\\u0078":2}','"\\ud800"','-0','-0.0','-0e8','NaN','1e999','\ufeff{}']:
  check('WIRE-REJECT-'+repr(t),'wire_rejection',lambda t=t:rejects(lambda:c.decode_json(t)))
 # Positive JSON identity / independent order checks.
 rng=random.Random(922)
 for k in range(50):
  data={'one':[rng.random(),{'boolean':bool(k%2),'null':None}],'unicode':'e\u0301😀','number':k,'edge':{'A':k+1,'B':k+2}}
  rev={name:data[name] for name in reversed(list(data))}
  check('ORDER-'+str(k),'canonical_order_and_types',lambda data=data,rev=rev:(req(c.canonical_json_bytes(data)==jcs(data)),req(c.canonical_json_bytes(data)==c.canonical_json_bytes(rev))))
 for left,right in [(True,1),(False,0),({'x':[True]},{'x':[1]}),('é','e\u0301')]:
  check('DISTINCT-'+repr(left),'canonical_order_and_types',lambda left=left,right=right:req(c.canonical_json_bytes(left)!=c.canonical_json_bytes(right)))
 # All candidate/realization declarations, exact identity and no support promotion.
 for cand in ('A','C'):
  for real in ('CI','OS','RG2b','PC','CI+PC'):
   def positive(cand=cand,real=real):
    par,i=fixture(cand,real);q=p.resolve_profile(par,i,expected_complete_profile_id=ident('grcv4-profile-sha256',i));req(q.identity_payload.candidate==cand);req(q.identity_payload.realization==real);req(jcs(q.params_resolved.to_payload())==jcs(par));req(not p.list_supported_profiles());rejects(lambda:p.get_supported_profile(q.complete_profile_id));return {'declared_only':True}
   check(f'DECL-{cand}-{real}','ten_declared_shapes',positive)
 # Mutation of every declared parameter section must invalidate old identity.
 for section,key in [('common','domain_id'),('candidate','chi_C'),('realization','tolerance'),('geometry','kappa_H'),('solver','conditioning_limit'),('charge','absolute_tolerance'),('lifecycle','history_policy_id')]:
  def changed(section=section,key=key):
   par,i=base();old=par[section][key];par[section][key]=old+1 if type(old) in (int,float) else old+'_changed';return rejects(lambda:p.resolve_profile(par,i))
  check('STALE-'+section,'profile_cross_bindings',changed)
 # Required keys and extra keys across all parameter record types.
 schemas={}
 for cand in ('A','C'):
  for real in ('CI','OS','RG2b','PC','CI+PC'):
   par,_=fixture(cand,real)
   for section,v in par.items():
    if isinstance(v,dict):schemas[v['schema_version']]=(section,v)
 for sv,(section,value) in schemas.items():
  cl=p._PARAMETER_CLASSES[sv]
  for key in value:
   def missing(cl=cl,value=value,key=key):
    d=copy.deepcopy(value);del d[key];return rejects(lambda:cl.from_payload(d))
   check(sv+'-MISSING-'+key,'closed_record_schema',missing)
  def extra(cl=cl,value=value):
   d=copy.deepcopy(value);d['unregistered_field']=1;return rejects(lambda:cl.from_payload(d))
  check(sv+'-EXTRA','closed_record_schema',extra)
 # Integer-typed runtime data must be genuine integral values, not only schema-valid.
 for real,section in [('CI','realization'),('RG2b','realization'),('CI+PC','realization'),('OS','solver')]:
  for value in (1.0,10.0,float(2**53-1)):
   for route in ('from_payload','direct'):
    def typed(real=real,section=section,value=value,route=route):
     par,i=fixture('C',real);par[section]['iteration_limit']=value;cl=p._PARAMETER_CLASSES[par[section]['schema_version']]
     record=cl.from_payload(par[section]) if route=='from_payload' else cl(**par[section])
     got=record.iteration_limit
     req(type(got) is int,f'{type(record).__name__}.{route}: iteration_limit={got!r} ({type(got).__name__}), declared int; operator.index fails')
     req(operator.index(got)==int(value));return {'value':got}
    check(f'INT-{real}-{value}-{route}','typed_integer_records',typed)
  for value in (True,False,0,-1,1.5,float(2**53)):
   def badint(real=real,section=section,value=value):
    par,_=fixture('C',real);par[section]['iteration_limit']=value;return rejects(lambda:p.resolve_parameters(par))
   check(f'INT-REJECT-{real}-{value}','integer_domain_rejection',badint)
 # Same complete identity but actual field type/index usability differs.
 def equal_profile_type_counterexample():
  par,i=base();par['solver']['iteration_limit']=10;reidentify(par,i);x=p.resolve_profile(par,i)
  par['solver']['iteration_limit']=10.0;reidentify(par,i);y=p.resolve_profile(par,i)
  req(x.complete_profile_id==y.complete_profile_id);req(x==y)
  req(type(x.params_resolved.solver.iteration_limit) is type(y.params_resolved.solver.iteration_limit),f'equal records and ID {x.complete_profile_id} carry int versus float iteration_limit')
 check('INT-EQUAL-PROFILE-DIFFERENT-TYPE','typed_integer_records',equal_profile_type_counterexample)
