  try:decoded=c.decode_json(raw)
  except c.V4WireError as e:raise AssertionError('schema-valid resolved profile cannot decode canonical payload: '+str(e))
  recovered=p.resolve_profile(decoded['params_resolved'],decoded['identity_payload'],expected_complete_profile_id=decoded['complete_profile_id']);req(recovered.complete_profile_id==q.complete_profile_id)
 check('PROFILE-CANONICAL-LARGE-FLOAT','numeric_codec_composition',big_profile,'integration_contract')
 # References: positive nonuniform field, permutations, rehashing cannot prove equality.
 subs={v['vector_id']:copy.deepcopy(v['payload']) for v in B['subdigest_identity_vectors']}
 for real in ('CI','OS','RG2b','PC','CI+PC'):
  def reference_case(real=real,mismatch=False,number_only=False):
   par,i=fixture('C',real)
