   p.validate_profile_references(q,live_edge_ids=list(reversed(w)),k4_preimage=subs['SUBDIGEST-K4-BASE'],reference_hodge_preimage=h)
   return {'reference_weights':w,'no_graph_or_SPD_admission':True}
